head.script:
scwin.onpageload = function() {

};

//spanAll 에 boolean 값으로 제어
scwin.trigger1_onclick = function (e) {
    gridView1.spanAll(false);
};

//spanAll 에 Number 로 제어
scwin.trigger2_onclick = function (e) {
    gridView1.spanAll(0);
};


	scwin.checkRows = function() {
		const tbody = WebSquare.wUnit.getDomById("gridView1_body_tbody");
		const rows = Array.from(tbody.getElementsByTagName("tr"));
		let reVal = 0

		rows.forEach((row, index) => {
			if (row.classList.contains("w2grid_lastRow") || row.classList.contains("w2grid_hidedRow")) {
				console.log("멈춘 tr:", index);
			}else{
				reVal = index;
			}
			console.log("현재 tr:", index); 
		});
		return reVal;
	}

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_0_2').querySelector('span').classList.contains('w2grid_plus');
	}		
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_1_2').querySelector('span').classList.contains('w2grid_plus');
	}		
	scwin.checkVal3 = function() {
		return !WebSquare.wUnit.getDomById('gridView1_cell_2_2').querySelector('span').classList.contains('w2grid_minus');
	}			
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");				

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
